"""vad_adapt — 三个窗口/阈值的【运行时自适应】，全部落说话人档案

① 判定停止(停止窗):  拼接 → +1帧(32ms)；连续20段干净 → −1帧
② 预滚(砍多少):      keep = 640 − ahead_trim_ms；段首能量比>0.35 → 少砍40ms；连续15段全静音 → 多砍40ms
③ 起判(何时触发输入): 持续有声>1.5s却没切出段 → prob−0.03(下限0.25)/hits→1；60s无漏 → 每60s回收+0.01(上限0.40)
档案: opencode_fastpath/vad_profiles.json  {"<说话人>": {...}}
说话人: env OPENCODE_SPEAKER(默认 default)
"""
from __future__ import annotations

import json
import os
import time
from pathlib import Path

HERE = Path(__file__).resolve().parent
PROFILES = HERE / "vad_profiles.json"
MIN_M, MAX_M = 8, 30
CLEAN_DECAY_EVERY = 20


def speaker() -> str:
    return os.environ.get("OPENCODE_SPEAKER", "default")


def load(speaker_id=None) -> dict:
    try:
        d = json.loads(PROFILES.read_text(encoding="utf-8"))
        return d.get(speaker_id or speaker(), {})
    except Exception:
        return {}


def save(misses: int, source: str, speaker_id=None, extra=None):
    try:
        d = json.loads(PROFILES.read_text(encoding="utf-8")) if PROFILES.exists() else {}
    except Exception:
        d = {}
    rec = {"misses": int(misses), "source": source, "ts": time.time()}
    if extra:
        rec.update(extra)
    d[speaker_id or speaker()] = rec
    PROFILES.write_text(json.dumps(d, ensure_ascii=False, indent=2), encoding="utf-8")
    return rec


class AdaptiveVad:
    def __init__(self, agent, speaker_id=None):
        self.agent = agent
        self.speaker = speaker_id or speaker()
        self.clean = 0
        self.n_stitch = 0
        self.n_adjust = 0
        self.min_m, self.max_m = MIN_M, MAX_M
        # 预滚（减法）
        self.trim_ms = None
        self.n_clip = 0
        self.low_streak = 0
        self.min_trim, self.max_trim = 0, 500
        # 起判（何时触发输入）
        self._voice_since = 0.0
        self._noise = 0.001
        self._last_miss = 0.0
        self._last_recover = 0.0
        self.n_miss = 0

    # ---------- 基础 ----------
    def _sm(self):
        return getattr(getattr(self.agent, "seg", None), "sm", None)

    def _beh(self):
        return getattr(getattr(self.agent, "cfg", None), "behavior", {}) or {}

    def _log(self, msg, level=None):
        try:
            from dlog import log
            log(msg, "MIC", level=level)
        except Exception:
            print(msg, flush=True)

    def current(self):
        sm = self._sm()
        return int(getattr(sm, "required_misses", 16)) if sm is not None else None

    def _save_state(self, why):
        b = self._beh()
        save(int(b.get("vad_required_misses") or self.current() or 16), "adapt", self.speaker,
             extra={"ahead_trim_ms": self.current_trim(b),
                    "prob": float(getattr(self._sm(), "prob_threshold", 0.3) or 0.3),
                    "hits": int(getattr(self._sm(), "required_hits", 1) or 1),
                    "n_miss": self.n_miss, "n_clip": self.n_clip,
                    "n_adjust": self.n_adjust, "why": why})

    # ---------- ① 停止窗 ----------
    def set_misses(self, misses, why):
        return self.set_window_ms(int(misses) * 32, why)

    def set_window_ms(self, ms, why):
        ms = int(max(self.min_m * 32, min(self.max_m * 32, int(ms))))
        sm = self._sm()
        old_ms = int(getattr(sm, "required_misses", 0)) * 32 if sm is not None else 0
        if sm is not None:
            sm.required_misses = int(round(ms / 32.0))
        seg = getattr(self.agent, "seg", None)
        try:
            if seg is not None and hasattr(seg, "silence_frames") and not hasattr(seg, "sm"):
                fm = float(getattr(seg, "frame_ms", 30) or 30)
                seg.silence_frames = max(1, int(round(ms / fm)))
        except Exception:
            pass
        try:
            if getattr(self.agent, "cfg", None) is not None:
                self.agent.cfg.behavior["vad_silence_ms"] = ms
        except Exception:
            pass
        if old_ms != ms:
            self.n_adjust += 1
            self._log(f"   [OPENCODE] 静音判定窗 {old_ms}→{ms}ms"
                      f"（silero misses={int(round(ms/32.0))} / segmenter silence_frames="
                      f"{max(1, int(round(ms/30.0)))}；{why}）",
                      level=("info" if "校准" in str(why) else None))
            self._save_state(why)
        return ms

    # ---------- ② 预滚（640 基准减法） ----------
    def current_trim(self, b=None):
        b = b if isinstance(b, dict) else self._beh()
        if "ahead_trim_ms" in b:
            return int(b["ahead_trim_ms"])
        return max(0, 640 - int(b.get("ahead_cap_ms", 640)))

    def set_trim(self, ms, why):
        b = getattr(getattr(self.agent, "cfg", None), "behavior", None)
        if not isinstance(b, dict):
            return
        ms = int(max(self.min_trim, min(self.max_trim, int(ms))))
        old = self.current_trim(b)
        if ms == old:
            return
        b["ahead_trim_ms"] = ms
        b["ahead_cap_ms"] = max(0, 640 - ms)
        self.trim_ms = ms
        self.n_adjust += 1
        self._log(f"   [OPENCODE] 预滚裁剪 {old}→{ms}ms（VAD 640ms → 保留 {640-ms}ms；{why}）")
        self._save_state(why)

    def set_preroll(self, pre, why):
        """把【预滚】三个参数写进内存配置 + 档案（现场校准用）

        ⚠️ 血债（2026-10-19 合成音频实测）：校准用一段"起音很硬"的音频时，
        recommend_preroll 会算出 onset_margin=80ms / ahead_cap=300ms / frac=0.1
        —— 那等于把起音余量砍到 1/5，直接造成"吞前面"。这里加【下限】兜住：
          起音余量 ≥ 250ms ｜ 预滚保留 ≥ 500ms ｜ 总长比例 ≥ 0.30
        """
        b = getattr(getattr(self.agent, "cfg", None), "behavior", None)
        if not isinstance(b, dict):
            return
        _cur_om = int(b.get("onset_margin_ms", 250) or 250)
        _cur_cap = int(b.get("ahead_cap_ms", 640) or 640)
        _cur_frac = float(b.get("ahead_frac", 0.30) or 0.30)
        # 原则：**校准只许更保守（多留预滚），不许更贪（多砍）** —— 血债：硬起音音频会被
        # 算成 onset_margin=80/frac=0.1 → 起音被吞。所以下限 = max(绝对下限, 当前值)。
        _om = max(250, _cur_om, int(pre.get("onset_margin_ms", 250)))
        _cap = max(500, min(640, _cur_cap), int(pre.get("ahead_cap_ms", 640)))
        _frac = max(0.30, _cur_frac, float(pre.get("ahead_frac", 0.30)))
        if (_om, _cap, round(_frac, 3)) != (int(pre.get("onset_margin_ms", 250)),
                                            int(pre.get("ahead_cap_ms", 640)),
                                            round(float(pre.get("ahead_frac", 0.30)), 3)):
            self._log(f"   [OPENCODE] 预滚推荐值会被夹到「只多留不更砍」→ "
                      f"onset_margin={_om}ms / ahead_cap={_cap}ms / ahead_frac={_frac:.2f}"
                      f"（推荐值 {pre.get('onset_margin_ms')}/{pre.get('ahead_cap_ms')}/"
                      f"{pre.get('ahead_frac')}，当前 {_cur_om}/{_cur_cap}/{_cur_frac:.2f}）")
        b["onset_margin_ms"] = _om
        b["ahead_frac"] = _frac
        self.set_trim(max(0, 640 - _cap), why)   # 写 trim/cap
        self._save_state(why)
        self._log(f"   [OPENCODE] 预滚已校正：onset_margin={b['onset_margin_ms']}ms "
                  f"ahead_cap={640 - self.current_trim()}ms（砍 {self.current_trim()}ms）"
                  f"ahead_frac={b['ahead_frac']}"
                  f"（段首能量比 p90={pre.get('head_ratio_p90', 0):.2f}，"
                  f"疑似切起音 {pre.get('onset_clip_rate', 0):.0f}%；{why}）",
                  level=("info" if "校准" in str(why) else None))

    def on_segment_head(self, ratio):
        if ratio is None:
            return
        cur = self.current_trim()
        if ratio > 0.35:
            self.n_clip += 1
            self.low_streak = 0
            if cur > self.min_trim:
                self.set_trim(cur - 40, f"段首能量比 {ratio:.2f}（起音被切）")
        elif ratio < 0.06:
            self.low_streak += 1
            if self.low_streak >= 15:
                self.low_streak = 0
                if cur < self.max_trim:
                    self.set_trim(cur + 40, "连续 15 段段首全静音（可多砍）")
        else:
            self.low_streak = 0

    # ---------- ③ 起判（何时触发输入） ----------
    def on_block(self, blk, got_segment):
        try:
            import numpy as np
            x = np.asarray(blk, dtype=np.float32).ravel()
            rms = float(np.sqrt(np.mean(x * x))) if x.size else 0.0
        except Exception:
            return
        now = time.time()
        if rms < self._noise:
            self._noise += 0.2 * (rms - self._noise)
        else:
            self._noise += 0.002 * (rms - self._noise)
        thr = max(0.004, self._noise * 3.0)
        if rms > thr:
            if not self._voice_since:
                self._voice_since = now
        else:
            self._voice_since = 0.0
        if got_segment:
            self._voice_since = 0.0
        sm = self._sm()
        if sm is None:
            return
        if self._voice_since and (now - self._voice_since) > 1.5:
            self._voice_since = 0.0
            self._last_miss = now
            self.n_miss += 1
            prob = float(getattr(sm, "prob_threshold", 0.3))
            hits = int(getattr(sm, "required_hits", 1))
            # ★ 用户实测：起判漏掉短口令/起音 —— 这条"系统自己发现漏检"的消息必须 INFO 可见
            if prob > 0.25:
                sm.prob_threshold = round(prob - 0.03, 2)
                self._log(f"   ⚠️ 疑似漏检（1.5s 持续有声但没出段，第 {self.n_miss} 次）"
                          f"→ 起判放宽：prob {prob:.2f}→{sm.prob_threshold}", level="info")
                self._save_state("起判放宽")
            elif hits > 1:
                sm.required_hits = 1
                self._log(f"   ⚠️ 疑似漏检（第 {self.n_miss} 次）→ 起判放宽：hits→1"
                          f"（prob 已到下限 0.25）", level="info")
                self._save_state("起判放宽")
        elif (now - self._last_miss) > 60:
            if (now - self._last_recover) > 60:
                self._last_recover = now
                prob = float(getattr(sm, "prob_threshold", 0.3))
                # ★ 修正（2026-10-19 用户实测）：回收上限必须 = 【配置里的值】，
                #   不能硬编码 0.40 —— 否则用户把灵敏度调到 0.30，60s 一次 +0.01
                #   会在 10 分钟内爬回 0.40，又开始漏检（"我明明调过啊"）。
                _cap = float(self._beh().get("vad_prob_threshold", 0.30) or 0.30)
                if prob < _cap:
                    sm.prob_threshold = round(min(_cap, prob + 0.01), 3)
                    self._log(f"   [OPENCODE] 起判回收：prob → {sm.prob_threshold}"
                              f"（60s 无漏判；上限 {_cap:.2f} = 配置值）")
                    self._save_state("起判回收")

    # ---------- ① 停止窗的其它信号 ----------
    def on_stitch(self):
        self.n_stitch += 1
        self.clean = 0
        cur = self.current()
        if cur is not None and self.n_stitch % 2 == 1:
            self.set_misses(cur + 1, f"拼接×{self.n_stitch}")

    def on_clean(self):
        self.clean += 1
        if self.clean >= CLEAN_DECAY_EVERY:
            self.clean = 0
            cur = self.current()
            if cur is not None:
                self.set_misses(cur - 1, f"连续{CLEAN_DECAY_EVERY}段无拼接")


def apply_at_startup(agent, speaker_id=None):
    a = AdaptiveVad(agent, speaker_id)
    rec = load(a.speaker)
    sm = a._sm()
    # 停止窗
    if rec.get("misses") and sm is not None:
        want = int(rec["misses"])
        if int(getattr(sm, "required_misses", 0)) != want:
            a.set_window_ms(want * 32, f"档案({rec.get('source','?')})")
    # 起判
    if sm is not None:
        if rec.get("prob"):
            sm.prob_threshold = float(rec["prob"])
        if rec.get("hits"):
            sm.required_hits = int(rec["hits"])
    base = a.current() or 16
    a.min_m = max(MIN_M, base - 8)
    a.max_m = min(MAX_M, base + 8)
    a._log(f"   [OPENCODE] 自适应已启用 说话人={a.speaker}｜判定停止窗={a.current()}帧"
           f"({(a.current() or 0)*32}ms, 可调区间 {(a.min_m)*32}~{(a.max_m)*32}ms)"
           f"｜预滚砍 {a.current_trim()}ms（640→{640-a.current_trim()}ms）"
           f"｜起判 prob={getattr(sm,'prob_threshold',0.4)}/hits={getattr(sm,'required_hits',2)}"
           f"｜ASR增益上限={int(a._beh().get('asr_gain_cap', 200))}×")
    return a
